```javascript
import { Group, Mesh, PlaneGeometry, BoxGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.order = 'YXZ';

  // ============================================================================
  // DESIGN TOKENS
  // ============================================================================
  const TILE_WIDTH = 1.0;
  const TILE_HEIGHT = 0.62;
  const GRID_GAP = 0.25;
  const GRID_COLS = 3;
  const GRID_ROWS = 2;
  const TOTAL_GRID_WIDTH = GRID_COLS * TILE_WIDTH + (GRID_COLS - 1) * GRID_GAP;
  const TOTAL_GRID_HEIGHT = GRID_ROWS * TILE_HEIGHT + (GRID_ROWS - 1) * GRID_GAP;
  const KICKER_OFFSET_Y = 0.3;

  const colorPaperHex = '#e8ecf2';
  const colorPaperRGB = { r: 232 / 255, g: 236 / 255, b: 242 / 255 };

  const brandMarks = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  // ============================================================================
  // BUILD BACKDROP GRADIENT PLANE (stage)
  // ============================================================================
  const backdropGeometry = new PlaneGeometry(8, 6);
  const backdropMaterial = new MeshStandardNodeMaterial();

  const gradientTop = vec3(26 / 255, 26 / 255, 34 / 255);
  const gradientBot = vec3(18 / 255, 18 / 255, 24 / 255);
  backdropMaterial.colorNode = mix(gradientTop, gradientBot, uv().y);
  backdropMaterial.metalness = uniform(0.0);
  backdropMaterial.roughness = uniform(1.0);
  backdropMaterial.emissiveIntensity = 0.0;

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ============================================================================
  // BRUSHED METAL TILE MATERIAL (instanced for all 6 tiles)
  // ============================================================================
  const createTileMaterial = () => {
    const mat = new MeshStandardNodeMaterial();

    const tileGradTop = vec3(26 / 255, 26 / 255, 34 / 255);
    const tileGradBot = vec3(18 / 255, 18 / 255, 24 / 255);
    mat.colorNode = mix(tileGradTop, tileGradBot, uv().y);

    mat.metalness = uniform(0.5);
    mat.roughness = uniform(0.55);
    mat.anisotropyIntensity = uniform(0.6);
    mat.anisotropyRotation = uniform(0.0);
    mat.clearcoat = uniform(0.2);
    mat.clearcoatRoughness = uniform(0.3);
    mat.emissiveIntensity = 0.0;

    return mat;
  };

  // ============================================================================
  // GRID CONTAINER (tile root, positioned and centered correctly)
  // ============================================================================
  const gridContainer = new Group();

  // Center the grid: offset so the geometric center lands at (0, 0)
  gridContainer.position.x = -TOTAL_GRID_WIDTH / 2;
  gridContainer.position.y = -TOTAL_GRID_HEIGHT / 2;
  gridContainer.position.z = 0;

  root.add(gridContainer);

  // ============================================================================
  // BUILD 6 TILES (3x2 grid) WITH CHAMFER VIA BOX GEOMETRY
  // ============================================================================
  const tiles = [];
  const tileObjects = [];
  const textMeshes = [];

  for (let row = 0; row < GRID_ROWS; row++) {
    for (let col = 0; col < GRID_COLS; col++) {
      const tileIndex = row * GRID_COLS + col;
      const brandMark = brandMarks[tileIndex] || '';

      // Compute tile position within grid container
      const tileX = col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
      const tileY = row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

      // Use BoxGeometry with small depth + bevel for chamfer effect
      const geometry = new BoxGeometry(TILE_WIDTH, TILE_HEIGHT, 0.04, 4, 4, 1);
      const material = createTileMaterial();
      const tile = new Mesh(geometry, material);

      tile.position.set(tileX, tileY, 0);
      tile.castShadow = true;
      tile.receiveShadow = true;

      gridContainer.add(tile);

      tiles.push({
        mesh: tile,
        brandMark,
        material,
      });
      tileObjects.push(tile);
    }
  }

  // ============================================================================
  // RENDER BRAND MARKS AS MONOCHROME TEXT (flat, at tile z + epsilon)
  // ============================================================================
  for (let i = 0; i < tiles.length; i++) {
    const tile = tiles[i];
    const row = Math.floor(i / GRID_COLS);
    const col = i % GRID_COLS;

    const tileX = col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
    const tileY = row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

    const textObj = ctx.fontAtlas.createText(tile.brandMark, {
      fontSize: 13,
      color: colorPaperHex,
      align: 'center',
      letterSpacingPx: 1.04,
    });

    textObj.position.set(tileX, tileY, 0.03);
    textObj.userData.tileIndex = i;
    textObj.userData.opacity = 0.78;

    // Apply opacity to all text geometry children
    if (textObj.children && textObj.children.length > 0) {
      textObj.children.forEach((child) => {
        if (child.material) {
          child.material.opacity = 0.78;
          child.material.transparent = true;
          child.material.needsUpdate = true;
        }
      });
    }

    gridContainer.add(textObj);
    textMeshes.push(textObj);
    tile.textMesh = textObj;
  }

  // ============================================================================
  // KICKER TEXT ("AS FEATURED IN") — positioned above grid
  // ============================================================================
  const kickerObj = ctx.fontAtlas.createText('AS FEATURED IN', {
    fontSize: 9,
    color: colorPaperHex,
    align: 'center',
    letterSpacingPx: 1.08,
  });

  kickerObj.position.set(
    TOTAL_GRID_WIDTH / 2 - gridContainer.position.x,
    TOTAL_GRID_HEIGHT / 2 - gridContainer.position.y + KICKER_OFFSET_Y,
    0.03
  );
  kickerObj.userData.opacity = 0.78;

  if (kickerObj.children && kickerObj.children.length > 0) {
    kickerObj.children.forEach((child) => {
      if (child.material) {
        child.material.opacity = 0.78;
        child.material.transparent = true;
        child.material.needsUpdate = true;
      }
    });
  }

  gridContainer.add(kickerObj);

  // ============================================================================
  // LIGHTING (key rake for anisotropic sweep + rim fill)
  // ============================================================================
  const { DirectionalLight, AmbientLight } = ctx.THREE;

  // Ambient fill (baseline)
  const ambientLight = new AmbientLight(0xffffff, 0.6);
  root.add(ambientLight);

  // Key light at 35° elevation, raking across tiles from left
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  const keyElevationRad = (35 * Math.PI) / 180;
  const keyDistance = 8;
  keyLight.position.set(
    keyDistance * Math.cos(keyElevationRad) * Math.cos(Math.PI * 0.25),
    keyDistance * Math.sin(keyElevationRad),
    keyDistance * Math.cos(keyElevationRad) * Math.sin(Math.PI * 0.25)
  );
  keyLight.target.position.set(0, 0, 0);
  keyLight.castShadow = true;
  root.add(keyLight);
  root.add(keyLight.target);

  // Rim light (opposite side, subtle accent)
  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-4, 0.5, 3);
  rimLight.target.position.set(0, 0, 0);
  rimLight.castShadow = false;
  root.add(rimLight);
  root.add(rimLight.target);

  // ============================================================================
  // ENTRANCE ANIMATION (stagger-cards: fade-up + translate-y, top-row first)
  // ============================================================================
  const entranceTl = gsap.timeline({ paused: false });

  // Stagger tiles by row, left-to-right on top row first
  tileObjects.forEach((tile, idx) => {
    const row = Math.floor(idx / GRID_COLS);
    const col = idx % GRID_COLS;
    // Top row first = lower stagger indices
    const staggerIdx = row * GRID_COLS + col;

    // Initial offset
    tile.position.y += 0.2;

    // Slide down entrance
    entranceTl.to(
      tile.position,
      {
        y: `-=0.2`,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      staggerIdx * 0.08
    );

    // Fade in text simultaneously
    const textMesh = tiles[idx].textMesh;
    if (textMesh) {
      textMesh.userData.opacity = 0.0;
      if (textMesh.children && textMesh.children.length > 0) {
        textMesh.children.forEach((child) => {
          if (child.material) {
            child.material.opacity = 0.0;
          }
        });
      }

      entranceTl.to(
        textMesh.userData,
        {
          opacity: 0.78,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          onUpdate() {
            if (textMesh.children && textMesh.children.length > 0) {
              textMesh.children.forEach((child) => {
                if (child.material) {
                  child.material.opacity = textMesh.userData.opacity;
                }
              });
            }
          },
        },
        staggerIdx * 0.08
      );
    }
  });

  // Kicker enters immediately with fade
  kickerObj.position.y += 0.2;
  kickerObj.userData.opacity = 0.0;
  if (kickerObj.children && kickerObj.children.length > 0) {
    kickerObj.children.forEach((child) => {
      if (child.material) {
        child.material.opacity = 0.0;
      }
    });
  }

  entranceTl.to(
    kickerObj.position,
    {
      y: `-=0.2`,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  entranceTl.to(
    kickerObj.userData,
    {
      opacity: 0.78,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate() {
        if (kickerObj.children && kickerObj.children.length > 0) {
          kickerObj.children.forEach((child) => {
            if (child.material) {
              child.material.opacity = kickerObj.userData.opacity;
            }
          });
        }
      },
    },
    0
  );

  // ============================================================================
  // HOVER INTERACTIONS (per-tile: text opacity + translateZ lift)
  // ============================================================================
  const hoverHandlers = {};

  tileObjects.forEach((tile, idx) => {
    const tileData = tiles[idx];

    hoverHandlers[`tile-${idx}-enter`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 1.0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0.05,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    hoverHandlers[`tile-${idx}-exit`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 0.78,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    tile.userData.tileIndex = idx;
  });

  // ============================================================================
  // CLEANUP
  // ============================================================================
  const allTimelines = [entranceTl];

  root.userData.cleanup = () => {
    // Kill all GSAP timelines
    allTimelines.forEach((tl) => {
      if (tl) tl.kill();
    });

    // Kill any active tile hover timelines
    tileObjects.forEach((tile) => {
      gsap.killTweensOf(tile.position);
    });
    textMeshes.forEach((text) => {
      gsap.killTweensOf(text.userData);
    });
    gsap.killTweensOf(kickerObj.userData);
    gsap.killTweensOf(kickerObj.position);

    // Dispose geometries and materials
    backdrop.geometry.dispose();
    backdrop.material.dispose();

    tileObjects.forEach((tile) => {
      tile.geometry.dispose();
      tile.material.dispose();
    });

    textMeshes.forEach((text) => {
      text.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });

    kickerObj.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });

    ambientLight.dispose();
    keyLight.dispose();
    rimLight.dispose();
  };

  // ============================================================================
  // ATTACH EVENT HANDLERS
  // ============================================================================
  root.userData.handlers = hoverHandlers;

  return root;
}
